export const meta = {
  name: 'drift-reconciliation',
  description: 'Audit 58 in_progress beads against landed upstream work; verify closures adversarially',
  phases: [
    { title: 'Check', detail: '9 agents, 7 beads each, gh/git evidence' },
    { title: 'Verify', detail: 'adversarial confirm of each proposed close' },
    { title: 'Deep', detail: 'mybd-zgxf vs #5006/#5008 CAS work' },
  ],
}

const S = args.scratch
const TARGET = budget.total ?? 200_000

const CHECK_SCHEMA = {
  type: 'object',
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          recommendation: { type: 'string', enum: ['close', 'unclaim', 'keep', 'human'] },
          reason: { type: 'string', description: 'one or two sentences' },
          evidence: { type: 'string', description: 'concrete verifiable refs: PR numbers + merge state, commit SHAs, issue closure, branch names' },
        },
        required: ['id', 'recommendation', 'reason', 'evidence'],
      },
    },
  },
  required: ['results'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    verdict: { type: 'string', enum: ['confirm-close', 'reject'] },
    reason: { type: 'string' },
  },
  required: ['id', 'verdict', 'reason'],
}

const RULES = `Ground rules:
- Read-only recon. Do NOT run any \`bd\` or \`dolt\` command (embedded-Dolt locking; the orchestrator owns bd serially). Do NOT edit or write any file.
- Work from /var/home/matt/dev/mybd. Upstream repo is gastownhall/beads — always pass --repo gastownhall/beads to gh. The nested beads source clone is bd-main/ (use git -C bd-main log --all --grep=... , git -C bd-main branch -a, etc.).
- Landed recently upstream (2026-07-23/24 merge flush) — check bead asks against these before assuming work is pending: #4878 migration-chain hardening (claims to fix gh#4690, gh#4695, gh#4353); #5006 claim verify-by-re-read + #5008 --if-assignee/--if-status CAS guards; #4877 --graph full-field parity + migration 0059 (recompute NULL-gate is_blocked, may bear on gh#4468); Jim Wordelman be-* backlog (#3971 label filters, #3663 PURGE, #3920 mem-profile, #3919 migration progress, #4160 max-rows tests, #3632 test-DB refusal, #3710, #4022, #4029); maphew plugin-docs batch (#4969-#4976); import fixes #4963/#4964; proxied-server trio #5002/#5003/#4997.`

phase('Check')
const batchCount = 9
const checked = await pipeline(
  Array.from({ length: batchCount }, (_, i) => i),
  (i) =>
    agent(
      `You are auditing possibly-stale issue-tracker claims in the maphew/mybd coordination repo, which tracks maintainer work on upstream gastownhall/beads.

Read ${S}/batches.json (a JSON array of 9 batches). Your batch is index ${i}. Each element is a bead: {id, title, updated_at, external_ref, assignee, notes, description}. external_ref like "gh-iss-4353" means upstream issue gastownhall/beads#4353. Notes often reference PRs, branches, and worktrees.

For EACH bead in your batch decide one of:
- "close": strong, verifiable evidence the ask landed or was resolved upstream (merged PR, closed issue that covers the bead's actual ask, commit on upstream main). Name the exact PR/issue/SHA and its state in evidence.
- "unclaim": no evidence of in-flight work (no open PR, no recent branch commits, no activity in notes) and updated_at is more than ~5 days old — the claim is dead weight hiding the bead from bd ready.
- "keep": genuinely active — an open PR awaiting review/CI, recent branch commits (check git -C bd-main branch -a and log), or updated within ~3 days with a live thread.
- "human": resolution requires the owner's judgment (design stance, policy).

How to check: gh issue view N --repo gastownhall/beads --json state,closedAt,title ; gh pr list --repo gastownhall/beads --search "..." --state all ; gh pr view N --repo gastownhall/beads --json state,mergedAt ; git -C bd-main log --all --oneline --grep="<keyword>". Beads whose notes mention a PR: verify that PR's current state rather than trusting the note.

Special case: if bead mybd-2avs is in your batch, mark it keep (it is this very sweep, running now).

Be skeptical in BOTH directions: don't recommend close without naming the covering change; don't recommend keep just because notes sound busy — notes describe the past.

${RULES}

Return via structured output: results for every bead in batch ${i}, in order.`,
      { label: `check:batch${i}`, phase: 'Check', model: 'sonnet', schema: CHECK_SCHEMA }
    ),
  (res, i) => {
    if (!res) return null
    const closes = res.results.filter((r) => r.recommendation === 'close')
    if (!closes.length) return { batch: i, results: res.results, verdicts: [] }
    if (budget.spent() > TARGET * 0.85) {
      log(`budget guard: skipping adversarial verify for batch ${i} (${closes.length} closes unverified)`)
      return { batch: i, results: res.results, verdicts: closes.map((c) => ({ id: c.id, verdict: 'reject', reason: 'unverified (budget guard) — orchestrator must spot-check' })) }
    }
    return parallel(
      closes.map((c) => () =>
        agent(
          `Adversarially verify a proposed issue closure in the mybd coordination repo (tracks work on upstream gastownhall/beads).

Bead ${c.id} is proposed for closure.
Claimed reason: ${c.reason}
Claimed evidence: ${c.evidence}

Your job: try to REFUTE this. Check with gh (--repo gastownhall/beads) and git -C bd-main that (a) the cited PRs/issues/commits actually exist in the claimed state (merged/closed), and (b) they actually cover the bead's ask — read the bead record in ${S}/batches.json (search for the id) and compare the ask against what the cited change does. A merged PR that only partially addresses the bead is grounds to reject. If evidence is vague, unverifiable, or mismatched, verdict is reject. Default to reject when uncertain.

${RULES}

Return {id: "${c.id}", verdict, reason}.`,
          { label: `verify:${c.id}`, phase: 'Verify', schema: VERDICT_SCHEMA }
        )
      )
    ).then((vs) => ({ batch: i, results: res.results, verdicts: vs.filter(Boolean) }))
  }
)

phase('Deep')
const zgxf = await agent(
  `Deep drift-check for bead mybd-zgxf (P0): "bd update --claim is not a hard CAS under true sub-second concurrency (load-tested)" — upstream issue gastownhall/beads#4657, triaged tri:claim on 2026-07-17.

Since then upstream merged (2026-07-24): #5006 "fix(claim): verify claim-family writes by re-read under a degraded server (bd-zccb9)" and #5008 "feat(update): conditional compare-and-set guards --if-assignee/--if-status (bd-wsqvw)".

Read the bead record at ${S}/zgxf.json. Then: gh issue view 4657 --repo gastownhall/beads (full body + comments); gh pr view 5006 --repo gastownhall/beads --json title,body,files; gh pr diff 5006 --repo gastownhall/beads | head -400; same for 5008. Also check git -C bd-main log upstream/main --oneline --grep=claim -i --since=2026-07-17 for anything else relevant.

Question: does the landed work give --claim true hard-CAS semantics under sub-second same-issue contention as the issue demands, or is it partial (e.g. re-read verification narrows but does not close the race; CAS guards exist but --claim does not use them by default)? Be precise about the mechanism.

Deliver: (1) verdict: resolved / partially-resolved / not-resolved; (2) mechanism analysis in a few sentences; (3) recommended bead action (close with reason / keep with updated note / human) and a suggested note text (2-4 sentences) the orchestrator can paste into the bead.

${RULES}`,
  { label: 'deep:zgxf-vs-CAS', phase: 'Deep' }
)

log(`spent ~${Math.round(budget.spent() / 1000)}k of ${Math.round(TARGET / 1000)}k target`)
return { checked: checked.filter(Boolean), zgxf }

export const meta = {
  name: 'ecuthiell-pr-sweep',
  description: 'Author-clustered review of ecuthiell open PRs 4979/4968/4949/4929/4928',
  phases: [
    { title: 'Review', detail: 'one reviewer per PR, full thread + diff + drift' },
    { title: 'Verify', detail: 'adversarial check of each verdict' },
  ],
}

const PRS = [4979, 4968, 4949, 4929, 4928]
const TARGET = budget.total ?? 200_000

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    pr: { type: 'integer' },
    classification: { type: 'string', enum: ['merge', 'merge-fix', 'fix-merge', 'easy-win', 'retire', 'reject', 'needs-author', 'needs-deeper-review'] },
    maintainer_can_edit: { type: 'boolean' },
    behind_main: { type: 'string', description: 'how far behind main + conflict status' },
    changes_requested_state: { type: 'string', description: 'what the CHANGES_REQUESTED review(s) asked, and whether each item is now addressed on the branch' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' },
          issue: { type: 'string' },
          fix: { type: 'string', description: 'concrete fix a builder could apply, or empty if author-judgment' },
          blocking: { type: 'boolean' },
        },
        required: ['file', 'issue', 'fix', 'blocking'],
      },
    },
    action_plan: { type: 'string', description: 'exact next steps: what to fix on the branch, what comment to post, merge method, or why retire/reject' },
    risk: { type: 'string', enum: ['low', 'medium', 'high'] },
  },
  required: ['pr', 'classification', 'maintainer_can_edit', 'behind_main', 'changes_requested_state', 'findings', 'action_plan', 'risk'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    pr: { type: 'integer' },
    verdict: { type: 'string', enum: ['confirm', 'revise'] },
    reason: { type: 'string' },
    corrections: { type: 'string', description: 'if revise: what the assessment got wrong' },
  },
  required: ['pr', 'verdict', 'reason'],
}

const RULES = `Ground rules:
- Read-only. Do NOT run any bd or dolt command. Do NOT edit/write files. Do NOT post anything to GitHub (no gh pr comment/review/merge/close) — this pass only assesses.
- Work from /var/home/matt/dev/mybd. Upstream repo: gastownhall/beads — always pass --repo gastownhall/beads to gh. Beads source clone: bd-main/ (git -C bd-main ...; upstream remote = gastownhall/beads). You may fetch PR refs read-only: git -C bd-main fetch upstream pull/<N>/head:refs/heads/tmp-review-<N> is NOT allowed (creates refs) — instead use git -C bd-main fetch upstream pull/<N>/head and inspect FETCH_HEAD, or rely on gh pr diff.
- Maintainer philosophy (PR_MAINTAINER_GUIDELINES.md): maximize contributor value; prefer fix-merge (maintainer commits on the contributor branch) over request-changes; retire only when superseded/landed elsewhere; preserve attribution.
- Cite findings as file:line. Be concrete enough that a builder agent could apply your fixes without rediscovering context.`

phase('Review')
const reviews = await pipeline(
  PRS,
  (n) =>
    agent(
      `Maintainer review of gastownhall/beads PR #${n} by ecuthiell (part of an author-clustered sweep of their 5 open PRs; all are marked CHANGES_REQUESTED).

Gather, at minimum:
1. gh pr view ${n} --repo gastownhall/beads --json title,body,state,mergeable,maintainerCanModify,baseRefName,headRefName,statusCheckRollup
2. The full review history: gh pr view ${n} --repo gastownhall/beads --json reviews,comments ; inline threads via gh api repos/gastownhall/beads/pulls/${n}/comments — identify exactly what the CHANGES_REQUESTED review(s) demanded and check the CURRENT branch state for whether each demand was addressed (reviews may be stale).
3. The diff: gh pr diff ${n} --repo gastownhall/beads (read all of it if reasonably sized).
4. Drift: how far behind upstream/main is the branch (git -C bd-main rev-list --count, merge-base) and whether main has since changed/landed anything overlapping (git -C bd-main log upstream/main --oneline -- <touched paths> since the PR's base).
5. Correctness: review the change itself for bugs, platform pitfalls (several of ecuthiell's PRs are Windows/CI/script related), and simpler alternatives.

Then classify per the maintainer triage groups (merge / merge-fix / fix-merge / easy-win / retire / reject / needs-author / needs-deeper-review) and produce a concrete action_plan. If stale CHANGES_REQUESTED reviews are actually resolved, say so explicitly — that unblocks a merge verdict.

${RULES}`,
      { label: `review:pr${n}`, phase: 'Review', schema: REVIEW_SCHEMA }
    ),
  (rev, n) => {
    if (!rev) return null
    if (budget.spent() > TARGET * 0.9) {
      log(`budget guard: skipping verify for PR ${n}`)
      return { review: rev, verdict: { pr: n, verdict: 'confirm', reason: 'unverified (budget guard) — orchestrator spot-check required' } }
    }
    return agent(
      `Adversarially verify a maintainer PR assessment for gastownhall/beads PR #${n} (author ecuthiell).

The assessment: ${JSON.stringify(rev)}

Try to refute it. Priorities: (a) if it claims CHANGES_REQUESTED items are addressed, check the actual review threads and current branch content yourself; (b) if it recommends merge/fix-merge, look for a disqualifying problem it missed (correctness, platform breakage, overlap with something that already landed on main); (c) if it recommends retire/reject, verify the superseding/landing claim is real — retiring live contributor value is the costly error; (d) check maintainer_can_edit and mergeability claims. Verdict 'revise' with corrections if anything material is wrong; otherwise 'confirm'.

${RULES}`,
      { label: `verify:pr${n}`, phase: 'Verify', schema: VERDICT_SCHEMA }
    ).then((v) => ({ review: rev, verdict: v }))
  }
)

log(`spent ~${Math.round(budget.spent() / 1000)}k of ${Math.round(TARGET / 1000)}k target`)
return { reviews: reviews.filter(Boolean) }
